const COMMON_HEADERS = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "strict-origin-when-cross-origin",
  "strict-transport-security": "max-age=31536000; includeSubDomains; preload",
  "permissions-policy": "accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=()",
};

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.protocol === "http:") {
      url.protocol = "https:";
      return Response.redirect(url.toString(), 301);
    }
    const p = url.pathname.replace(/\/+$/, "") || "/";

    if (p === "/" || p === "/index.html") {
      return new Response(INDEX_HTML, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "text/html; charset=utf-8",
          "cache-control": "public, max-age=300, stale-while-revalidate=86400",
        },
      });
    }

    if (p === "/style.css") {
      return new Response(STYLE_CSS, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "text/css; charset=utf-8",
          "cache-control": "public, max-age=3600, stale-while-revalidate=86400",
        },
      });
    }

    if (p === "/app.js") {
      return new Response(APP_JS, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/javascript; charset=utf-8",
          "cache-control": "public, max-age=3600, stale-while-revalidate=86400",
        },
      });
    }

    if (p === "/sound.js") {
      return new Response(SOUND_JS, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/javascript; charset=utf-8",
          "cache-control": "public, max-age=3600, stale-while-revalidate=86400",
        },
      });
    }

    if (p === "/zeno-engine.js") {
      return new Response(ZENO_ENGINE_JS, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/javascript; charset=utf-8",
          "cache-control": "public, max-age=3600, stale-while-revalidate=86400",
        },
      });
    }

    if (p === "/favicon.svg") {
      return new Response(FAVICON_SVG, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "image/svg+xml",
          "cache-control": "public, max-age=86400",
        },
      });
    }

    if (p === "/og.svg") {
      return new Response(OG_SVG, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "image/svg+xml",
          "cache-control": "public, max-age=86400",
        },
      });
    }

    if (p === "/robots.txt") {
      return new Response(ROBOTS_TXT, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "text/plain; charset=utf-8",
          "cache-control": "public, max-age=86400",
        },
      });
    }

    if (p === "/sitemap.xml") {
      return new Response(SITEMAP_XML, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/xml; charset=utf-8",
          "cache-control": "public, max-age=86400",
        },
      });
    }

    if (p === "/manifest.webmanifest" || p === "/manifest.json") {
      return new Response(MANIFEST_JSON, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/manifest+json; charset=utf-8",
          "cache-control": "public, max-age=3600, stale-while-revalidate=86400",
        },
      });
    }

    if (p === "/sw.js") {
      return new Response(SW_JS, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/javascript; charset=utf-8",
          "cache-control": "public, max-age=0, must-revalidate",
        },
      });
    }

    // Apple Wallet Passes (8b-is Crew, Mom/Alexandra, Dad/Chris, 8b-is Corporate Fleet)
    if (p === "/apple-wallet/zeno.pkpass" || p === "/apple-wallet/peter.pkpass" || p === "/apple-wallet/crew.pkpass" || p === "/zeno.pkpass") {
      const binaryString = atob(PKPASS_ULTRA_BASE64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return new Response(bytes.buffer, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/vnd.apple.pkpass",
          "content-disposition": 'attachment; filename="zeno_ultra.pkpass"',
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/apple-wallet/alexandra.pkpass" || p === "/apple-wallet/mom.pkpass" || p === "/alexandra.pkpass") {
      const binaryString = atob(PKPASS_ALEXANDRA_BASE64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return new Response(bytes.buffer, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/vnd.apple.pkpass",
          "content-disposition": 'attachment; filename="zeno_alexandra.pkpass"',
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/apple-wallet/chris.pkpass" || p === "/apple-wallet/dad.pkpass" || p === "/chris.pkpass") {
      const binaryString = atob(PKPASS_CHRIS_BASE64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return new Response(bytes.buffer, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/vnd.apple.pkpass",
          "content-disposition": 'attachment; filename="zeno_chris.pkpass"',
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/apple-wallet/8b-is.pkpass" || p === "/apple-wallet/company.pkpass" || p === "/8b-is.pkpass") {
      const binaryString = atob(PKPASS_8B_BASE64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return new Response(bytes.buffer, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/vnd.apple.pkpass",
          "content-disposition": 'attachment; filename="zeno_8b_is.pkpass"',
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/healthz" || p === "/beacon.json") {
      return new Response(BEACON_JSON, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/json; charset=utf-8",
          "access-control-allow-origin": "*",
          "cache-control": "no-cache",
        },
      });
    }

    if (p === "/spec/vaked-protocol.hcl" || p === "/vaked-protocol.hcl") {
      return new Response(VAKED_PROTOCOL_HCL, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "text/plain; charset=utf-8",
          "access-control-allow-origin": "*",
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/.well-known/acp.json" || p === "/acp.json") {
      return new Response(JSON.stringify(ACP_MANIFEST, null, 2), {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/json; charset=utf-8",
          "access-control-allow-origin": "*",
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/spec/STRIPE_COMPATIBILITY_MCP_ACP.md" || p === "/rfc-002" || p === "/acp-spec") {
      return new Response(STRIPE_ACP_MD, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "text/markdown; charset=utf-8",
          "access-control-allow-origin": "*",
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/spec/research/ICML_2026_WORKSHOPS_8B_IS.md" || p === "/icml-2026") {
      return new Response(ICML_WORKSHOPS_MD, {
        headers: {
          ...COMMON_HEADERS,
          "content-type": "text/markdown; charset=utf-8",
          "access-control-allow-origin": "*",
          "cache-control": "public, max-age=3600",
        },
      });
    }

    if (p === "/api/v1/stripe/webhook" && request.method === "POST") {
      const json = (obj, status = 200) => new Response(JSON.stringify(obj), {
        status,
        headers: { ...COMMON_HEADERS, "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
      });
      const secret = env && env.STRIPE_WEBHOOK_SECRET;
      if (!secret) {
        // Fail closed: never acknowledge payment events we cannot authenticate.
        return json({ received: false, error: "webhook_not_configured" }, 503);
      }
      const sigHeader = request.headers.get("stripe-signature") || "";
      const raw = await request.text();
      const parts = {};
      for (const kv of sigHeader.split(",")) {
        const i = kv.indexOf("=");
        if (i > 0) {
          const k = kv.slice(0, i).trim();
          (parts[k] = parts[k] || []).push(kv.slice(i + 1).trim());
        }
      }
      const t = parseInt((parts.t || [])[0], 10);
      const v1s = parts.v1 || [];
      const now = Math.floor(Date.now() / 1000);
      if (!Number.isFinite(t) || v1s.length === 0) return json({ received: false, error: "missing_signature" }, 400);
      if (Math.abs(now - t) > 300) return json({ received: false, error: "timestamp_outside_tolerance" }, 400);
      const enc = new TextEncoder();
      const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
      const mac = new Uint8Array(await crypto.subtle.sign("HMAC", key, enc.encode(t + "." + raw)));
      const expected = Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("");
      const ctEq = (a, b) => {
        if (a.length !== b.length) return false;
        let d = 0;
        for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
        return d === 0;
      };
      if (!v1s.some((s) => ctEq(s, expected))) return json({ received: false, error: "invalid_signature" }, 400);
      let event;
      try { event = JSON.parse(raw); } catch { return json({ received: false, error: "invalid_json" }, 400); }
      // Verified acknowledgement only. Ledger posting + Sanpo Yoshi split happen in zeno_core
      // (apps/core/zeno_core/stripe_bridge.py), not at the edge.
      return json({ received: true, verified: true, eventId: event.id || null, type: event.type || null });
    }

    // Foken Gate Pre-Filter endpoint: /api/v1/gate
    if (p === "/api/v1/gate" && request.method === "POST") {
      try {
        const body = await request.json();
        const verdict = evaluateFokenInvoice(body);
        return new Response(JSON.stringify(verdict), {
          headers: {
            ...COMMON_HEADERS,
            "content-type": "application/json; charset=utf-8",
            "access-control-allow-origin": "*",
          },
        });
      } catch (err) {
        return new Response(
          JSON.stringify({ error: err.message, verdict: "FAIL" }),
          {
            status: 400,
            headers: {
              ...COMMON_HEADERS,
              "content-type": "application/json; charset=utf-8",
              "access-control-allow-origin": "*",
            },
          }
        );
      }
    }

    return new Response(
      JSON.stringify({ error: "Endpoint not found", path: url.pathname }),
      {
        status: 404,
        headers: {
          ...COMMON_HEADERS,
          "content-type": "application/json; charset=utf-8",
        },
      }
    );
  },
};

function evaluateFokenInvoice(invoice) {
  const invId = invoice.invoiceId || "unknown";

  const required = ["invoiceId", "version", "contributor", "work", "artifact", "valuation", "ipAssignment"];
  for (const f of required) {
    if (!invoice[f]) {
      return { invoiceId: invId, verdict: "FAIL", reason: "missing field '" + f + "'" };
    }
  }

  if (!/^0x[0-9a-fA-F]{40}$/.test(invoice.contributor)) {
    return { invoiceId: invId, verdict: "FAIL", reason: "invalid contributor address format" };
  }

  if (!invoice.artifact.provenanceHash?.startsWith("sha256://")) {
    return { invoiceId: invId, verdict: "FAIL", reason: "artifact provenance must start with sha256://" };
  }

  const fokens = invoice.valuation.selfAssessedFokens;
  if (typeof fokens !== "number" || fokens <= 0 || !Number.isInteger(fokens)) {
    return { invoiceId: invId, verdict: "FAIL", reason: "selfAssessedFokens must be a positive integer" };
  }

  const ip = invoice.ipAssignment;
  if (!ip.statement?.includes("IRREVOCABLE ASSIGNMENT") || !ip.signature?.startsWith("0x")) {
    return { invoiceId: invId, verdict: "FAIL", reason: "missing/unsigned IP assignment — no IP, no mint" };
  }

  const nu = invoice.netUtility;
  if (!nu || typeof nu.futureWorkAvoidedHours !== "number") {
    return { invoiceId: invId, verdict: "REVIEW", reason: "missing/invalid netUtility figures" };
  }

  const net = nu.futureWorkAvoidedHours - (nu.workAddedHours + 1.5 * nu.maintenanceDebtHours);
  if (net <= 0) {
    return {
      invoiceId: invId,
      verdict: "FAIL",
      reason: "net-negative utility (" + net + "): work added exceeds future work avoided",
      netUtility: net,
    };
  }

  return {
    invoiceId: invId,
    verdict: "PASS",
    reason: "eligible for human vote (net utility = " + net + ")",
    netUtility: net,
  };
}
